1	/**
2	 * 後端 API 一律走 Next.js 的 /api/[...path] proxy 轉發到 FutureClassroom.Api，
3	 * 所以呼叫端只用同源相對路徑。同源請求瀏覽器會自動帶上登入 cookie，
4	 * 不需要額外指定 credentials。
5	 */
6	export const BASE_PATH = process.env.NEXT_PUBLIC_BASE_PATH || "";
7	export const API_BASE = `${BASE_PATH}/api`;
8	
9	/** 後端回 401（未登入或 cookie 過期）時丟出；apiFetch 已經順手導回登入頁，呼叫端通常不用特別處理。 */
10	export class UnauthorizedError extends Error {
11	  constructor() {
12	    super("Unauthorized");
13	    this.name = "UnauthorizedError";
14	  }
15	}
16	
17	
18	export function startSsoLogin(): void {
19	  window.location.href = `${API_BASE}/auth/login`;
20	}
21	
22	/** 後端會先清掉本站 cookie，再轉去 NTU SSO gateway 結束 gateway 上的 session。 */
23	export function startSsoLogout(): void {
24	  window.location.href = `${API_BASE}/auth/logout`;
25	}
26	
27	/** window.location 不會自動補 Next.js 的 basePath，所以這裡要手動加。 */
28	export function redirectToLogin(): void {
29	  window.location.href = `${BASE_PATH}/login`;
30	}
31	
32	/**
33	 * Encode a URL path segment without double-encoding.
34	 * `useParams()` 可能是空白，也可能已經是 %20；兩邊都要編成單次 %20。
35	 */
36	export function encodeApiPathSegment(value: string): string {
37	  let current = value;
38	  for (let i = 0; i < 2; i++) {
39	    try {
40	      const decoded = decodeURIComponent(current);
41	      if (decoded === current) break;
42	      current = decoded;
43	    } catch {
44	      break;
45	    }
46	  }
47	  return encodeURIComponent(current);
48	}
49	
50	/** 帶 basePath 的 API fetch；遇到 401 直接導回登入頁並丟出 UnauthorizedError。 */
51	export async function apiFetch(
52	  path: string,
53	  init?: RequestInit,
54	): Promise<Response> {
55	  const response = await fetch(`${API_BASE}${path}`, init);
56	
57	  if (response.status === 401) {
58	    redirectToLogin();
59	    throw new UnauthorizedError();
60	  }
61	
62	  return response;
63	}
