317	function PageHeader({
318	  searchKeyword,
319	  onSearchKeywordChange,
320	  suggestions,
321	  title,
322	  searchPlaceholder,
323	  emptyMessage,
324	}: {
325	  searchKeyword: string;
326	  onSearchKeywordChange: (value: string) => void;
327	  suggestions: SearchSuggestion[];
328	  title: string;
329	  searchPlaceholder: string;
330	  emptyMessage: string;
331	}) {
332	  const router = useRouter();
333	  const headerRef = useRef<HTMLElement>(null);
334	  const headerHeightRef = useRef(0);
335	  const [isCollapsed, setIsCollapsed] = useState(false);
336	
337	  useEffect(() => {
338	    const header = headerRef.current;
339	    if (!header) return;
340	
341	    const scrollRoot =
342	      header.closest("main") instanceof HTMLElement
343	        ? (header.closest("main") as HTMLElement)
344	        : null;
345	    if (!scrollRoot) return;
346	
347	    // avoid expand/collapse thrashing when header height changes
348	    const COLLAPSE_AT = 64;
349	    const EXPAND_AT = 12;
350	
351	    const update = () => {
352	      const top = scrollRoot.scrollTop;
353	      setIsCollapsed((prev) => {
354	        if (!prev && top >= COLLAPSE_AT) return true;
355	        if (prev && top <= EXPAND_AT) return false;
356	        return prev;
357	      });
358	    };
359	
360	    headerHeightRef.current = header.offsetHeight;
361	    update();
362	    scrollRoot.addEventListener("scroll", update, { passive: true });
363	    return () => scrollRoot.removeEventListener("scroll", update);
364	  }, []);
365	
366	  // Keep scroll position stable while the header height animates
367	  useLayoutEffect(() => {
368	    const header = headerRef.current;
369	    if (!header) return;
370	
371	    const scrollRoot =
372	      header.closest("main") instanceof HTMLElement
373	        ? (header.closest("main") as HTMLElement)
374	        : null;
375	    if (!scrollRoot) return;
376	
377	    let rafId = 0;
378	    const startedAt = performance.now();
379	
380	    const tick = () => {
381	      const nextHeight = header.offsetHeight;
382	      const prevHeight = headerHeightRef.current;
383	      const delta = prevHeight - nextHeight;
384	
385	      if (prevHeight > 0 && delta !== 0) {
386	        scrollRoot.scrollTop += delta;
387	      }
388	      headerHeightRef.current = nextHeight;
389	
390	      if (performance.now() - startedAt < HEADER_TRANSITION_MS + 50) {
391	        rafId = requestAnimationFrame(tick);
392	      }
393	    };
394	
395	    rafId = requestAnimationFrame(tick);
396	    return () => cancelAnimationFrame(rafId);
397	  }, [isCollapsed]);
398	
399	  return (
400	    <header
401	      ref={headerRef}
402	      className={`sticky top-0 z-[60] -mx-4 px-4 sm:-mx-8 sm:px-8 bg-[#F2F2F2] transition-[padding,margin] duration-200 ease-out ${
403	        isCollapsed ? "py-4 sm:py-8 mb-4" : "pt-4 sm:pt-8 pb-4 sm:pb-6 mb-0"
404	      }`}
405	    >
406	      <div className="relative flex w-full flex-col md:flex-row md:items-center md:justify-end">
407	        <h1
408	          aria-hidden={isCollapsed}
409	          className={`text-2xl sm:title-1 font-bold text-gray-90 whitespace-nowrap overflow-hidden transition-all duration-200 ease-out md:absolute md:left-0 md:overflow-visible ${
410	            isCollapsed
411	              ? "max-h-0 opacity-0 pointer-events-none mb-0 md:max-h-none"
412	              : "max-h-12 opacity-100 mb-4 md:mb-0 md:max-h-none"
413	          }`}
414	        >
415	          {title}
416	        </h1>
417	
418	        <div
419	          className={`min-w-0 w-full transition-[width] duration-200 ease-out ${
420	            isCollapsed ? "md:w-full" : "md:w-[320px]"
421	          }`}
422	        >
423	          <SearchBar
424	            placeholder={searchPlaceholder}
425	            showDropdown
426	            value={searchKeyword}
427	            onChange={onSearchKeywordChange}
428	            suggestions={suggestions}
429	            onSearch={onSearchKeywordChange}
430	            emptyMessage={emptyMessage}
431	            onSelectSuggestion={(item) => {
432	              if (item.courseKey) router.push(`/course/${item.courseKey}`);
433	            }}
434	          />
435	        </div>
436	      </div>
437	    </header>
438	  );
439	}
