13	// 對應後端 /auth/me 回傳的 UserResponse.user（SsoEndpoints.cs）
14	export interface AuthUser {
15	  id: string;
16	  name: string;
17	  department: string | null;
18	  departmentZh: string | null;
19	  departmentEn: string | null;
20	  role: string;
21	}
22	
23	export type AuthStatus = "loading" | "authenticated" | "unauthenticated";
24	
25	interface AuthContextValue {
26	  user: AuthUser | null;
27	  status: AuthStatus;
28	}
29	
30	const AuthContext = createContext<AuthContextValue>({
31	  user: null,
32	  status: "loading",
33	});
34	
35	export function useAuth(): AuthContextValue {
36	  return useContext(AuthContext);
37	}
38	
39	const PUBLIC_PATHS = ["/login"]; // 其餘頁面未登入一律導回 /login
40	
41	export function AuthProvider({ children }: { children: React.ReactNode }) {
42	  const pathname = usePathname();
43	  const isPublicPath = PUBLIC_PATHS.includes(pathname);
44	  const [state, setState] = useState<AuthContextValue>({
45	    user: null,
46	    status: "loading",
47	  });
48	
49	  const loadUser = useCallback(async (): Promise<AuthContextValue> => {
50	    const response = await fetch(`${API_BASE}/auth/me`, {
51	      method: "GET",
52	      headers: { accept: "application/json" },
53	    });
54	
55	    if (!response.ok) return { user: null, status: "unauthenticated" };
56	
57	    const resBody = await response.json();
58	    const raw = resBody?.user;
59	    if (!raw) return { user: null, status: "unauthenticated" };
60	
61	    const user: AuthUser = {
62	      id: raw.id ?? "",
63	      name: raw.name ?? "",
